package com.lyra.studio; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; import android.webkit.WebView; import android.webkit.WebViewClient; import android.view.View; import android.app.Activity; import android.view.WindowManager; @DesignerComponent(version = 1, description = "Um custom webviewer que se adapta ao teclado virtual do dispositivo.", category = ComponentCategory.EXTENSION, nonVisible = false, iconName = "images/extension.png") @SimpleObject(external = true) public class KeyboardAwareWebView extends AndroidViewComponent { private WebView webView; private Activity activity; public KeyboardAwareWebView(ComponentContainer container) { super(container); this.activity = container.$context(); this.webView = new WebView(activity); this.webView.getSettings().setJavaScriptEnabled(true); this.webView.getSettings().setDomStorageEnabled(true); this.webView.setWebViewClient(new WebViewClient()); /* Ajusta a janela da atividade para redimensionar quando o teclado aparecer, evitando que cubra o conteudo do webviewer */ this.activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); container.$add(this); } @Override public View getView() { return webView; } @SimpleFunction(description = "Abre uma URL especifica no WebViewer.") public void GoToUrl(String url) { webView.loadUrl(url); } }